begin;
create function public.get_selected_quote_identity_reconfirmation_context_v1(p_quote_version_id uuid,p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$
declare context_value jsonb;proposals jsonb;existing jsonb;provider_value jsonb;effective_id uuid;effective jsonb;total_value bigint;begin
 if auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.can_read_quote((select quote_id from public.quote_versions where id=p_quote_version_id))then raise exception'QUOTE_IDENTITY_SCOPE_DENIED'using errcode='42501';end if;
 if p_page is null or p_page<1 or p_page>1000000 then raise exception'INVALID_QUOTE_IDENTITY_PAGE'using errcode='22023';end if;
 context_value:=private.selected_quote_identity_context_v1(p_quote_version_id);
 select p.id into effective_id from public.selected_quote_identity_proposals_v1 p join public.selected_quote_identity_responses_v1 r on r.proposal_id=p.id and r.decision='ACCEPT'and r.content_hash=p.content_hash and r.responded_by<>p.proposed_by where p.quote_version_id=p_quote_version_id and p.context_hash=context_value->>'context_hash'order by r.responded_at desc,p.id desc limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'content_hash',p.content_hash,'context_hash',p.context_hash,'provider_reason',p.reason,'proposed_at',p.proposed_at,'proposed_by',p.proposed_by,'client_party',p.client_party,'provider_party',p.provider_party,'decision',r.decision,'decision_reason',r.reason,'responded_by',r.responded_by,'responded_at',r.responded_at,'current',p.context_hash=context_value->>'context_hash','effective',coalesce(p.id=effective_id,false))order by p.proposed_at desc,p.id),'[]')into proposals from(select*from public.selected_quote_identity_proposals_v1 where quote_version_id=p_quote_version_id order by proposed_at desc,id desc limit 25 offset((p_page-1)*25))p left join public.selected_quote_identity_responses_v1 r on r.proposal_id=p.id;
 select jsonb_build_object('id',p.id,'content_hash',p.content_hash,'context_hash',p.context_hash,'provider_reason',p.reason,'proposed_at',p.proposed_at,'proposed_by',p.proposed_by,'client_party',p.client_party,'provider_party',p.provider_party,'decision',r.decision,'decision_reason',r.reason,'responded_by',r.responded_by,'responded_at',r.responded_at,'current',p.context_hash=context_value->>'context_hash','effective',coalesce(p.id=effective_id,false))into effective from public.selected_quote_identity_proposals_v1 p left join public.selected_quote_identity_responses_v1 r on r.proposal_id=p.id where p.id=effective_id;
 select count(*)into total_value from public.selected_quote_identity_proposals_v1 where quote_version_id=p_quote_version_id;
 provider_value:=private.effective_selected_quote_identity_snapshot_v1(p_quote_version_id);
 select jsonb_build_object('contract_id',c.id,'contract_version_id',v.id,'content_hash',v.content_hash,'status',c.status,'version',c.current_version,'refresh_required',(context_value->'current_client_party')is distinct from(select legal_snapshot from public.contract_parties where contract_version_id=v.id and party_role='CLIENT')or provider_value is distinct from(select legal_snapshot from public.contract_parties where contract_version_id=v.id and party_role='PROVIDER'),'signature_pending',exists(select 1 from public.signature_envelopes where contract_id=c.id and status not in('DRAFT','VOIDED')))into existing from public.selected_quote_contract_drafts_v1 m join public.contracts c on c.id=m.contract_id join public.contract_versions v on v.contract_id=c.id and v.version=c.current_version where m.quote_version_id=p_quote_version_id;
 return context_value||jsonb_build_object('existing_contract',existing,'can_propose_provider',private.has_org_role((context_value->>'provider_organization_id')::uuid,array['PROVIDER_OWNER','PROVIDER_MANAGER']),'can_accept_client',private.has_org_role((context_value->>'client_organization_id')::uuid,array['CLIENT_OWNER','CLIENT_ADMIN']),'proposals',proposals,'effective_proposal',effective,'page',p_page,'page_size',25,'total',total_value,'has_next',total_value>p_page::bigint*25);
end$$;
create function public.propose_selected_quote_identity_reconfirmation_v1(p_quote_version_id uuid,p_expected_context_hash text,p_registered_address text,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$
declare actor uuid:=auth.uid();context_value jsonb;provider_value jsonb;h text;cached jsonb;result jsonb;proposal_id uuid;address_value text;begin
 if actor is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.can_read_quote((select quote_id from public.quote_versions where id=p_quote_version_id))then raise exception'QUOTE_IDENTITY_PROPOSAL_DENIED'using errcode='42501';end if;
 context_value:=private.selected_quote_identity_context_v1(p_quote_version_id);
 if actor is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.has_org_role((context_value->>'provider_organization_id')::uuid,array['PROVIDER_OWNER','PROVIDER_MANAGER'])then raise exception'QUOTE_IDENTITY_PROPOSAL_DENIED'using errcode='42501';end if;
 if coalesce(p_expected_context_hash,'')!~'^[a-f0-9]{64}$'or length(btrim(coalesce(p_registered_address,'')))not between 5 and 1000 or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 or p_correlation_id is null then raise exception'INVALID_QUOTE_IDENTITY_PROPOSAL'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('quote_version_id',p_quote_version_id,'context_hash',p_expected_context_hash,'registered_address',btrim(p_registered_address),'reason',btrim(p_reason)));cached:=private.begin_contract_command((context_value->>'provider_organization_id')::uuid,'quote.identity.propose.v1',p_idempotency_key,h,actor);if cached is not null then return cached;end if;
 perform private.lock_contract_financial_parties_v1((context_value->>'client_organization_id')::uuid,(context_value->>'provider_organization_id')::uuid);perform pg_advisory_xact_lock(hashtextextended('service-request:'||(context_value->>'request_id'),0));
 context_value:=private.selected_quote_identity_context_v1(p_quote_version_id);
 if not private.has_org_role((context_value->>'provider_organization_id')::uuid,array['PROVIDER_OWNER','PROVIDER_MANAGER'])then raise exception'QUOTE_IDENTITY_PROPOSAL_DENIED'using errcode='42501';end if;
 if context_value->>'context_hash'is distinct from p_expected_context_hash then raise exception'STALE_QUOTE_IDENTITY_CONTEXT'using errcode='40001';end if;
 if jsonb_array_length(context_value->'blocked_reasons')>0 then raise exception'QUOTE_IDENTITY_NEW_COMMITMENT_BLOCKED'using errcode='55000';end if;
 address_value:=context_value->>'canonical_provider_address';
 if address_value is not null and regexp_replace(btrim(p_registered_address),'[[:space:]]+',' ','g')is distinct from regexp_replace(address_value,'[[:space:]]+',' ','g')then raise exception'PROVIDER_CANONICAL_ADDRESS_REQUIRED'using errcode='23514';end if;
 provider_value:=context_value->'provider_party_base'||jsonb_build_object('registered_address',coalesce(address_value,btrim(p_registered_address)));
 h:=private.canonical_request_hash(jsonb_build_object('context_hash',p_expected_context_hash,'client_party',context_value->'current_client_party','provider_party',provider_value,'reason',btrim(p_reason),'proposed_by',actor));
 insert into public.selected_quote_identity_proposals_v1(quote_version_id,request_id,client_organization_id,provider_organization_id,context_hash,client_party,provider_party,reason,proposed_by,content_hash)values(p_quote_version_id,(context_value->>'request_id')::uuid,(context_value->>'client_organization_id')::uuid,(context_value->>'provider_organization_id')::uuid,p_expected_context_hash,context_value->'current_client_party',provider_value,btrim(p_reason),actor,h)returning id into proposal_id;
 result:=jsonb_build_object('outcome','SELECTED_QUOTE_IDENTITY_PROPOSED','proposal_id',proposal_id,'content_hash',h,'status','PENDING_CLIENT_RESPONSE');
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values((context_value->>'provider_organization_id')::uuid,actor,'USER','quote.identity.proposed','selected_quote_identity_proposal',proposal_id::text,p_correlation_id,jsonb_build_object('quote_version_id',p_quote_version_id,'content_hash',h,'context_hash',p_expected_context_hash),repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values((context_value->>'provider_organization_id')::uuid,'selected_quote_identity_proposal',proposal_id::text,'SelectedQuoteIdentityProposedV1',p_correlation_id,result||jsonb_build_object('quote_version_id',p_quote_version_id,'context_hash',p_expected_context_hash,'client_organization_id',context_value->>'client_organization_id'),'quote-identity-proposal:'||proposal_id::text);
 perform private.finish_contract_command((context_value->>'provider_organization_id')::uuid,'quote.identity.propose.v1',p_idempotency_key,result);return result;
end$$;
create function public.respond_selected_quote_identity_reconfirmation_v1(p_proposal_id uuid,p_expected_content_hash text,p_decision text,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$
declare actor uuid:=auth.uid();p public.selected_quote_identity_proposals_v1%rowtype;context_value jsonb;h text;cached jsonb;result jsonb;begin
 select*into p from public.selected_quote_identity_proposals_v1 where id=p_proposal_id;
 if actor is null or auth.jwt()->>'aal'is distinct from'aal2'or p.id is null or p.proposed_by=actor or not private.has_org_role(p.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'])then raise exception'QUOTE_IDENTITY_INDEPENDENT_CLIENT_REQUIRED'using errcode='42501';end if;
 if coalesce(p_expected_content_hash,'')!~'^[a-f0-9]{64}$'or p_decision is null or p_decision not in('ACCEPT','DECLINE')or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 or p_correlation_id is null then raise exception'INVALID_QUOTE_IDENTITY_RESPONSE'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('proposal_id',p.id,'content_hash',p_expected_content_hash,'decision',p_decision,'reason',btrim(p_reason)));cached:=private.begin_contract_command(p.client_organization_id,'quote.identity.respond.v1',p_idempotency_key,h,actor);if cached is not null then return cached;end if;
 perform private.lock_contract_financial_parties_v1(p.client_organization_id,p.provider_organization_id);perform pg_advisory_xact_lock(hashtextextended('service-request:'||p.request_id::text,0));
 if p.content_hash is distinct from p_expected_content_hash then raise exception'STALE_QUOTE_IDENTITY_PROPOSAL'using errcode='40001';end if;
 if not private.has_org_role(p.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'])or p.proposed_by=actor then raise exception'QUOTE_IDENTITY_INDEPENDENT_CLIENT_REQUIRED'using errcode='42501';end if;
 context_value:=private.selected_quote_identity_context_v1(p.quote_version_id);
 if p_decision='ACCEPT'and(p.context_hash is distinct from context_value->>'context_hash'or jsonb_array_length(context_value->'blocked_reasons')>0)then raise exception'STALE_QUOTE_IDENTITY_CONTEXT'using errcode='40001';end if;
 insert into public.selected_quote_identity_responses_v1(proposal_id,decision,content_hash,reason,responded_by)values(p.id,p_decision,p.content_hash,btrim(p_reason),actor);
 result:=jsonb_build_object('outcome','SELECTED_QUOTE_IDENTITY_RESPONDED','proposal_id',p.id,'content_hash',p.content_hash,'decision',p_decision);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p.client_organization_id,actor,'USER','quote.identity.responded','selected_quote_identity_proposal',p.id::text,p_correlation_id,jsonb_build_object('content_hash',p.content_hash,'decision',p_decision,'reason',btrim(p_reason)),repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p.client_organization_id,'selected_quote_identity_proposal',p.id::text,'SelectedQuoteIdentityRespondedV1',p_correlation_id,result||jsonb_build_object('quote_version_id',p.quote_version_id,'provider_organization_id',p.provider_organization_id),'quote-identity-response:'||p.id::text);
 perform private.finish_contract_command(p.client_organization_id,'quote.identity.respond.v1',p_idempotency_key,result);return result;
end$$;
create function public.refresh_selected_quote_contract_draft_v1(p_contract_id uuid,p_expected_contract_version_id uuid,p_expected_content_hash text,p_expected_identity_context_hash text,p_identity_reconfirmation_id uuid,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$
declare actor uuid:=auth.uid();c public.contracts%rowtype;v public.contract_versions%rowtype;m public.selected_quote_contract_drafts_v1%rowtype;proposal public.selected_quote_identity_proposals_v1%rowtype;context_value jsonb;provider_value jsonb;client_value jsonb;h text;source_hash text;cached jsonb;result jsonb;new_version uuid;archived integer:=0;begin
 select*into c from public.contracts where id=p_contract_id;
 if actor is null or auth.jwt()->>'aal'is distinct from'aal2'or c.id is null or not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'])then raise exception'CONTRACT_DRAFT_REFRESH_DENIED'using errcode='42501';end if;
 if p_expected_contract_version_id is null or coalesce(p_expected_content_hash,'')!~'^[a-f0-9]{64}$'or coalesce(p_expected_identity_context_hash,'')!~'^[a-f0-9]{64}$'or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 or p_correlation_id is null then raise exception'INVALID_CONTRACT_DRAFT_REFRESH'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('contract_id',c.id,'expected_version_id',p_expected_contract_version_id,'expected_hash',p_expected_content_hash,'identity_context_hash',p_expected_identity_context_hash,'reconfirmation_id',p_identity_reconfirmation_id,'reason',btrim(p_reason)));cached:=private.begin_contract_command(c.client_organization_id,'contract.draft.refresh.v1',p_idempotency_key,h,actor);if cached is not null then return cached;end if;
 perform private.lock_contract_financial_parties_v1(c.client_organization_id,c.provider_organization_id);
 select*into m from public.selected_quote_contract_drafts_v1 where contract_id=c.id;
 if m.contract_id is null then raise exception'CANONICAL_SELECTED_QUOTE_CONTRACT_REQUIRED'using errcode='55000';end if;
 perform pg_advisory_xact_lock(hashtextextended('service-request:'||m.request_id::text,0));
 select*into c from public.contracts where id=p_contract_id for update;select*into v from public.contract_versions where contract_id=c.id and version=c.current_version;
 if not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'])then raise exception'CONTRACT_DRAFT_REFRESH_DENIED'using errcode='42501';end if;
 if v.id is distinct from p_expected_contract_version_id or v.content_hash is distinct from p_expected_content_hash then raise exception'STALE_CONTRACT_DRAFT'using errcode='40001';end if;
 if c.status not in('DRAFT','PENDING_SIGNATURE')or exists(select 1 from public.contract_signatures where contract_id=c.id)then raise exception'CONTRACT_SIGNATURE_PREVENTS_DRAFT_REFRESH'using errcode='55000';end if;
 context_value:=private.selected_quote_identity_context_v1(v.selected_quote_version_id);
 if context_value->>'context_hash'is distinct from p_expected_identity_context_hash then raise exception'STALE_QUOTE_IDENTITY_CONTEXT'using errcode='40001';end if;
 if jsonb_array_length(context_value->'blocked_reasons')>0 then raise exception'QUOTE_IDENTITY_NEW_COMMITMENT_BLOCKED'using errcode='55000';end if;
 client_value:=context_value->'current_client_party';
 if p_identity_reconfirmation_id is not null then
  select p.*into proposal from public.selected_quote_identity_proposals_v1 p join public.selected_quote_identity_responses_v1 r on r.proposal_id=p.id and r.decision='ACCEPT'and r.content_hash=p.content_hash and r.responded_by<>p.proposed_by where p.id=p_identity_reconfirmation_id and p.quote_version_id=v.selected_quote_version_id;
  if proposal.id is null or proposal.context_hash is distinct from context_value->>'context_hash'or proposal.client_party is distinct from client_value or proposal.id is distinct from(select p.id from public.selected_quote_identity_proposals_v1 p join public.selected_quote_identity_responses_v1 r on r.proposal_id=p.id and r.decision='ACCEPT'and r.content_hash=p.content_hash and r.responded_by<>p.proposed_by where p.quote_version_id=v.selected_quote_version_id and p.context_hash=context_value->>'context_hash'order by r.responded_at desc,p.id desc limit 1)then raise exception'ACCEPTED_CURRENT_QUOTE_IDENTITY_REQUIRED'using errcode='55000';end if;provider_value:=proposal.provider_party;
 elsif(context_value->>'original_provider_current')::boolean and not exists(select 1 from public.selected_quote_identity_proposals_v1 p join public.selected_quote_identity_responses_v1 r on r.proposal_id=p.id and r.decision='ACCEPT'where p.quote_version_id=v.selected_quote_version_id and p.context_hash=context_value->>'context_hash')then provider_value:=private.provider_quote_identity_snapshot_v1(v.selected_quote_version_id);
 else raise exception'ACCEPTED_CURRENT_QUOTE_IDENTITY_REQUIRED'using errcode='55000';end if;
 if client_value is null or provider_value is null or provider_value->>'country_code'is distinct from client_value->>'country_code'or provider_value->>'country_code'is distinct from(select country_code from public.contract_policy_versions_v1 where id=m.template_policy_version_id)then raise exception'CONTRACT_PARTY_JURISDICTION_MISMATCH'using errcode='55000';end if;
 if not exists(select 1 from public.contract_policy_versions_v1 p join public.contract_policy_decisions_v1 d on d.policy_version_id=p.id and d.decision='APPROVE'and d.content_hash=p.content_hash and d.decided_by<>p.created_by where p.id=m.template_policy_version_id and p.content_hash=v.clauses->>'template_content_hash')or not exists(select 1 from public.contract_policy_versions_v1 p join public.contract_policy_decisions_v1 d on d.policy_version_id=p.id and d.decision='APPROVE'and d.content_hash=p.content_hash and d.decided_by<>p.created_by where p.id=m.commission_policy_version_id and p.content_hash=v.commission_rule_snapshot->>'content_hash')then raise exception'ORIGINAL_APPROVED_CONTRACT_POLICIES_REQUIRED'using errcode='55000';end if;
 if exists(select 1 from public.signature_envelopes where contract_id=c.id and status not in('DRAFT','VOIDED'))then raise exception'CONTRACT_SIGNATURE_PREVENTS_DRAFT_REFRESH'using errcode='55000';end if;
 if client_value=(select legal_snapshot from public.contract_parties where contract_version_id=v.id and party_role='CLIENT')and provider_value=(select legal_snapshot from public.contract_parties where contract_version_id=v.id and party_role='PROVIDER')then raise exception'CONTRACT_DRAFT_IDENTITY_UNCHANGED'using errcode='55000';end if;
 -- The signature domain alone may certify a local never-prepared archive.
 if c.status='DRAFT'and exists(select 1 from public.signature_envelopes where contract_id=c.id and contract_version_id=v.id and status='DRAFT')and to_regprocedure('private.archive_unprepared_contract_envelopes_v1(uuid,uuid,text,uuid)')is not null then execute'select private.archive_unprepared_contract_envelopes_v1($1,$2,$3,$4)'into archived using c.id,v.id,left('Legal identity refresh: '||btrim(p_reason),1000),p_correlation_id;end if;
 if exists(select 1 from public.signature_envelopes e where e.contract_id=c.id and(e.status<>'VOIDED'or to_regprocedure('private.signature_envelope_void_is_recorded_v1(uuid)')is null))then raise exception'CONTRACT_SIGNATURE_PREVENTS_DRAFT_REFRESH'using errcode='55000';end if;
 if exists(select 1 from public.signature_envelopes where contract_id=c.id)then
  if exists(select 1 from public.signature_envelopes e where e.contract_id=c.id and not private.signature_envelope_void_is_recorded_v1(e.id))then raise exception'CONTRACT_SIGNATURE_PREVENTS_DRAFT_REFRESH'using errcode='55000';end if;
 end if;
 source_hash:=private.canonical_request_hash(jsonb_build_object('previous_contract_version_id',v.id,'previous_content_hash',v.content_hash,'request',v.request_snapshot,'quote',v.quote_snapshot,'clauses',v.clauses,'commission',v.commission_rule_snapshot,'client_party',client_value,'provider_party',provider_value,'price_minor',v.price_minor::text,'currency',v.currency,'identity_reconfirmation_id',p_identity_reconfirmation_id));
 insert into public.contract_versions(contract_id,version,selected_quote_version_id,request_snapshot,quote_snapshot,clauses,price_minor,currency,commission_rule_snapshot,content_hash,change_reason,created_by)values(c.id,c.current_version+1,v.selected_quote_version_id,v.request_snapshot,v.quote_snapshot,v.clauses,v.price_minor,v.currency,v.commission_rule_snapshot,source_hash,btrim(p_reason),actor)returning id into new_version;
 insert into public.contract_parties(contract_version_id,organization_id,party_role,legal_snapshot)values(new_version,c.client_organization_id,'CLIENT',client_value),(new_version,c.provider_organization_id,'PROVIDER',provider_value);
 insert into public.contract_items(contract_version_id,item_key,item_type,label_fr,label_ar,details,sort_order)select new_version,item_key,item_type,label_fr,label_ar,details,sort_order from public.contract_items where contract_version_id=v.id;
 update public.contracts set current_version=c.current_version+1,status='DRAFT',row_version=row_version+1,updated_at=clock_timestamp()where id=c.id;
 insert into public.selected_quote_contract_refreshes_v1(contract_id,previous_version_id,contract_version_id,identity_reconfirmation_id,context_hash,source_hash,reason,created_by)values(c.id,v.id,new_version,p_identity_reconfirmation_id,p_expected_identity_context_hash,source_hash,btrim(p_reason),actor);
 result:=jsonb_build_object('outcome','SELECTED_QUOTE_CONTRACT_DRAFT_REFRESHED','contract_id',c.id,'contract_version_id',new_version,'content_hash',source_hash,'version',c.current_version+1,'archived_unprepared_envelopes',archived,'status','DRAFT');
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,actor,'USER','contract.draft.identity_refreshed','contract',c.id::text,p_correlation_id,jsonb_build_object('previous_version_id',v.id,'contract_version_id',new_version,'source_hash',source_hash,'reconfirmation_id',p_identity_reconfirmation_id,'reason',btrim(p_reason),'archived_unprepared_envelopes',archived),repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract',c.id::text,'SelectedQuoteContractDraftRefreshedV1',p_correlation_id,result||jsonb_build_object('previous_contract_version_id',v.id,'quote_version_id',v.selected_quote_version_id,'identity_reconfirmation_id',p_identity_reconfirmation_id),'contract-draft-identity-refresh:'||new_version::text);
 perform private.finish_contract_command(c.client_organization_id,'contract.draft.refresh.v1',p_idempotency_key,result);return result;
end$$;
-- Use a newly accepted legal snapshot for new drafts without changing the
-- original quote anchor or old idempotent generation responses.
do $$declare definition text;target text;begin
 select pg_get_functiondef('public.get_selected_quote_contract_context_v1(uuid)'::regprocedure)into definition;
 target:='select jsonb_build_object(''contract_id'',contract_id,''contract_version_id'',contract_version_id)into existing from public.selected_quote_contract_drafts_v1 where quote_version_id=selected;';
 if strpos(definition,target)=0 then raise exception'CONTRACT_REFRESH_CONTEXT_PATCH_TARGET_MISSING';end if;
 definition:=replace(definition,target,'select jsonb_build_object(''contract_id'',m.contract_id,''contract_version_id'',v.id)into existing from public.selected_quote_contract_drafts_v1 m join public.contracts c on c.id=m.contract_id join public.contract_versions v on v.contract_id=c.id and v.version=c.current_version where m.quote_version_id=selected;');
